    public sealed class AccountScreenController : IUomdScreenController
    {
        private readonly UomdSceneRouter _router;
        public UomdScreenId ScreenId => UomdScreenId.Account;
        public AccountScreenController(UomdSceneRouter router) => _router = router;

        public Awaitable OnEnterAsync(VisualElement screenRoot)
        {
            var panel = new VisualElement();
            panel.AddToClassList("uomd-panel");

            var title = new Label("ACCOUNT · ACCESSIBILITY · UMP PRIVACY · 21-TABLE DATA ERASURE");
            title.AddToClassList("uomd-title-md");

            var motionBtn = UomdUiKit.CreateButton("TOGGLE REDUCED MOTION", () =>
            {
                _router.Session.ReducedMotion = !_router.Session.ReducedMotion;
                UomdUiKit.ShowToast(screenRoot, $"Reduced Motion: {_router.Session.ReducedMotion}");
            });
            motionBtn.style.marginTop = 12;

            var flashBtn = UomdUiKit.CreateButton("TOGGLE REDUCED FLASH", () =>
            {
                _router.Session.ReduceFlash = !_router.Session.ReduceFlash;
                UomdUiKit.ShowToast(screenRoot, $"Reduced Flash: {_router.Session.ReduceFlash}");
            });
            flashBtn.style.marginTop = 8;

            var umpBtn = UomdUiKit.CreateButton("PRIVACY & AD CONSENT (GOOGLE UMP)", async () =>
            {
                await _router.PlatformBridge.ShowPrivacyOptionsFormAsync();
                UomdUiKit.ShowToast(screenRoot, "Privacy options updated.");
            });
            umpBtn.style.marginTop = 8;

            var deleteBtn = UomdUiKit.CreateButton("DELETE ACCOUNT PERMANENTLY", async () =>
            {
                bool confirmed = await UomdUiKit.ShowConfirmModalAsync(
                    screenRoot,
                    "PERMANENT ACCOUNT ERASURE",
                    "This action permanently deletes your account across all 21 D1 tables and clears your AndroidKeyStore token.",
                    "Irreversible GDPR / Play Console Data Safety Deletion");
                if (confirmed)
                {
                    await _router.PlatformBridge.ClearEncryptedSessionTokenAsync();
                    UomdUiKit.ShowToast(screenRoot, "Account scheduled for erasure.");
                }
            }, danger: true);
            deleteBtn.style.marginTop = 16;

            panel.Add(title);
            panel.Add(motionBtn);
            panel.Add(flashBtn);
            panel.Add(umpBtn);
            panel.Add(deleteBtn);
            screenRoot.Add(panel);
            return default;
        }

        public void OnTick(float deltaTime) { }
        public void OnExit() { }
    }

